function toRow(d: any) {
  const b = (v: boolean | undefined) => (v === undefined ? undefined : v ? 1 : 0);
  return { ...d, out_of_hours_cover: b(d.out_of_hours_cover), labour_included: b(d.labour_included), parts_included: b(d.parts_included) };
