40	  const db = getDb();
41	  if (!db.prepare("SELECT 1 FROM customers WHERE id = ?").get(d.customer_id)) throw notFound("Customer");
42	  if (d.site_id) {
43	    const s = db.prepare("SELECT customer_id FROM sites WHERE id = ?").get(d.site_id) as any;
