.eng-day { font-family: var(--font-cond); font-weight: 600; font-size: 17px; margin: 16px 4px 8px; color: var(--ink-2); }
.eng-card { display: block; background: #fff; border: 1px solid var(--rule); border-radius: 8px; padding: 14px; color: inherit; }
.eng-card + .eng-card { margin-top: 10px; }
.eng-card:hover { text-decoration: none; border-color: var(--rule-strong); }
.eng-card .time { font-family: var(--font-cond); font-size: 20px; font-weight: 600; }
.eng-card.live { border: 2px solid var(--ok); }
.eng-section { background: #fff; border: 1px solid var(--rule); border-radius: 8px; margin-top: 12px; }
.eng-section > h2 { font-size: 17px; padding: 12px 14px; border-bottom: 1px solid var(--rule); display: flex; justify-content: space-between; align-items: center; }
.eng-section > .inner { padding: 12px 14px; }
.eng button, .eng .btn { min-height: 46px; font-size: 16px; padding: 10px 16px; }
.eng button.small { min-height: 36px; font-size: 14px; padding: 6px 12px; }
.eng input, .eng select, .eng textarea { font-size: 16px; padding: 11px 12px; }
.eng .bigaction { width: 100%; font-size: 18px; min-height: 56px; }
.eng .actions-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
.tel { display: inline-flex; align-items: center; gap: 6px; font-weight: 600; }
.cond { display: grid; grid-template-columns: repeat(4, 1fr); gap: 6px; }
.cond button { min-height: 42px; font-size: 14px; padding: 6px; }
.cond button.on.good { background: var(--ok); color: #fff; border-color: var(--ok); }
.cond button.on.attention { background: var(--amber); color: #fff; border-color: var(--amber); }
.cond button.on.failed { background: var(--heat); color: #fff; border-color: var(--heat); }
.cond button.on.not_checked { background: var(--ink-3); color: #fff; border-color: var(--ink-3); }
.photos { display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; }
.photos img { width: 100%; aspect-ratio: 1; object-fit: cover; border-radius: 6px; border: 1px solid var(--rule); }
.outcomes { display: grid; gap: 8px; }
.outcomes label { display: flex; gap: 10px; align-items: flex-start; border: 1px solid var(--rule-strong); border-radius: 8px; padding: 12px; font-weight: 500; }
.outcomes label.on { border-color: var(--primary); background: var(--primary-soft); }
.outcomes input { width: auto; margin-top: 3px; }
canvas.sig { width: 100%; height: 150px; border: 1px dashed var(--rule-strong); border-radius: 6px; background: #fff; touch-action: none; }

