          {["sent", "rejected"].includes(q.status) && can("quote.write") && <button onClick={async () => { const r: any = await run(() => api.post(`/quotes/${q.id}/revise`), "Revision created"); if (r) nav(`/quotes/${r.id}/edit`); }}>Revise</button>}
