            <b>{l.name}</b>
            <div className="small muted">{l.kind === "van" ? "Van stock" : "Store"}{l.below_min ? ` · ${l.below_min} below min` : ""}{l.negative ? <span style={{ color: "var(--heat)" }}> · {l.negative} negative</span> : ""}</div>
          </div>
