  const parts = useQuery({ queryKey: ["parts", ""], queryFn: () => api.get(`/parts${qs({})}`) });
  const [supplierId, setSupplierId] = useState(params.get("supplier") ?? "");
  const [locationId, setLocationId] = useState("");
  const [expected, setExpected] = useState("");
